(function(){var loadHandler=window['sl_{73A53C97-72DA-45CF-9CFF-054D6C4F2812}'];loadHandler&&loadHandler(108, '<div id="spr0_10537bff"><div id="spr1_10537bff" class="kern slide"><img id="img2_10537bff" src="data:image/png;base64," width="1280px" height="720px" alt="" style="left:0px;top:0px;"/><div id="spr3_10537bff" style="left:986.15px;top:648.5px;"><div id="spr4_10537bff"><img id="img0_10537bff" src="data:image/png;base64," width="273.75" height="62.25" alt="" style="left:0.06px;top:-0.094px;"/></div></div></div><div id="spr2_10537bff" class="kern slide"><div id="svg0_10537bff" style="left:1067.273px;top:628.69px;"><svg width="186" height="38" viewBox="0 0 186 38"><path fill="#ffe699" d="M0,0 h185.566 v37.159 h-185.566 Z"/></svg></div><div id="spr5_10537bff" style="left:1067.273px;top:628.69px;"><div style="width:0px;"><span id="txt0_10537bff" class="nokern relpos" data-width="75.595703" style="left:9.6px;top:8.408px;">Book A  </span> <span id="txt1_10537bff" class="nokern relpos" data-width="85.686195" style="left:9.593px;top:5.95px;">Page 19</span></div></div><div id="spr6_10537bff" style="left:1224.769px;"><div id="svg1_10537bff" style="left:5.031px;top:4.251px;"><svg width="47" height="28" viewBox="0 0 47 28"><path fill="#c00000" d="M0,0 h46.08 v27.429 h-46.08 Z"/></svg></div><div id="svg2_10537bff" style="left:0px;top:0px;"><svg width="65" height="28" viewBox="0 0 65 28"><path fill="none" d="M0,0 h64.174 v27.433 h-64.174 Z"/></svg></div><div id="spr7_10537bff"><div style="width:0px;"><span id="txt2_10537bff" class="nokern" data-width="42.155083" style="left:9.598px;top:2.268px;">END</span></div></div></div><div id="spr8_10537bff" style="left:230.202px;top:342.207px;"><div id="spr9_10537bff"><img id="img1_10537bff" src="data:image/png;base64," width="726.75" height="324" alt="" style="left:-0.113px;top:-0.134px;"/></div></div><div id="spr10_10537bff" style="left:120.15px;top:143.12px;"><div style="width:0px;"><span id="txt3_10537bff" class="nokern relpos" dir="auto" style="left:9.6px;top:6.246px;">•</span> <span id="txt4_10537bff" class="nokern relpos" data-width="78.832031" style="left:33.065px;top:6.246px;">Cochlea:</span> <span id="txt5_10537bff" class="nokern relpos" data-width="616.328125" style="left:33.058px;top:6.246px;"> Spiral cavity within which sound waves are converted into action potential.</span></div></div><div id="spr11_10537bff" style="left:120.15px;top:34.442px;"><div style="width:0px;"><span id="txt6_10537bff" class="nokern" data-width="138.714844" style="left:9.6px;top:6.656px;">3. Inner Ear:</span></div><div style="width:0px;"><span id="txt7_10537bff" class="nokern" data-width="618.415344" style="left:9.6px;top:44.88px;">Fluid-filled chamber that sorts sound waves based on tone (frequency) and</span></div><div style="width:0px;"><span id="txt8_10537bff" class="nokern" data-width="299.878906" style="left:9.6px;top:69.746px;">converts them to an action potential.</span></div></div><div id="spr12_10537bff" style="left:120.15px;top:187.677px;"><div style="width:0px;"><span id="txt9_10537bff" class="nokern relpos" dir="auto" style="left:9.6px;top:6.246px;">•</span> <span id="txt10_10537bff" class="nokern relpos" data-width="132.726562" style="left:33.065px;top:6.246px;">Organ of Corti:</span> <span id="txt11_10537bff" class="nokern relpos" data-width="796.915344" style="left:33.058px;top:6.246px;"> Vibrations of the oval window set the liquid into motion inside the cochlea that in turn causes the</span></div><div style="width:0px;"><span id="txt12_10537bff" class="nokern" data-width="758.433594" style="left:39.6px;top:31.113px;">hair cells (mechanoreceptors) to move. This movement is converted into an action potential.</span></div></div><div id="spr13_10537bff" style="left:120.15px;top:256.542px;"><div style="width:0px;"><span id="txt13_10537bff" class="nokern relpos" dir="auto" style="left:9.6px;top:6.246px;">•</span> <span id="txt14_10537bff" class="nokern relpos" data-width="137.949219" style="left:33.065px;top:6.246px;">Auditory nerve:</span> <span id="txt15_10537bff" class="nokern relpos" data-width="672.355469" style="left:33.058px;top:6.246px;"> A collection of sensory neurons which forward the message to the temporal lobe.</span></div></div><div id="spr14_10537bff" style="left:120.15px;top:299.374px;"><div style="width:0px;"><span id="txt16_10537bff" class="nokern relpos" dir="auto" style="left:9.6px;top:6.246px;">•</span> <span id="txt17_10537bff" class="nokern relpos" data-width="138.924469" style="left:33.065px;top:6.246px;">Round window:</span> <span id="txt18_10537bff" class="nokern relpos" data-width="394.296875" style="left:33.058px;top:6.246px;"> Dampens the vibrations of the endolymph fluid.</span></div></div></div></div>', '{"s":[]}');})();